/* @author MILO-GAO(高振銘)@2020 */ package page2020.util;import java.text.DateFormat;import java.text.SimpleDateFormat;import java.util.Calendar;import java.util.Date;public class TimeUtil {	public static DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd");	public static DateFormat dateFormat2 = new SimpleDateFormat("yyyy/MM/dd");	public static DateFormat dateFormat3 = new SimpleDateFormat("MM/dd");	public static DateFormat dateFormatE = new SimpleDateFormat("yyyyMMdd");	public static DateFormat timeFormat = new SimpleDateFormat("HH:mm:ss");	public static DateFormat timeFormatE = new SimpleDateFormat("HHmmss");	public static DateFormat datetimeFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");	public static DateFormat datetimeFormat2 = new SimpleDateFormat("yyyy/MM/dd HH:mm:ss");	public static DateFormat monthFormat = new SimpleDateFormat("yyyy-MM");	public static DateFormat yearFormat = new SimpleDateFormat("yyyy");	public static DateFormat weekFormat = new SimpleDateFormat("ww");	public static void midnight(Calendar calendar) {		calendar.set(Calendar.HOUR_OF_DAY, 0);		calendar.set(Calendar.MINUTE, 0);		calendar.set(Calendar.SECOND, 0);		calendar.set(Calendar.MILLISECOND, 0);	}	public static Date midnight(Date date) {		Calendar calendar = Calendar.getInstance();		calendar.setTime(date);		midnight(calendar);		return calendar.getTime();	}	public static Date midnight(Date date, int days) {		Calendar calendar = Calendar.getInstance();		calendar.setTime(date);		calendar.add(Calendar.DATE, days);		midnight(calendar);		return calendar.getTime();	}	public static String date() {		return dateFormat.format(new Date());	}	public static String date(Date date) {		return dateFormat.format(date);	}	public static String date2(Date date) {		return dateFormat2.format(date);	}	public static String date3(Date date) {		return dateFormat3.format(date);	}	public static String dateE(Date date) {		return dateFormatE.format(date);	}	public static String time() {		return timeFormat.format(new Date());	}	public static String time(Date date) {		return timeFormat.format(date);	}	public static String timeE(Date date) {		return timeFormatE.format(date);	}	public static String datetime() {		return datetimeFormat.format(new Date());	}	public static String datetime(Date date) {		return datetimeFormat.format(date);	}	public static String datetime2() {		return datetimeFormat2.format(new Date());	}	public static String datetime2(Date date) {		return datetimeFormat2.format(date);	}	public static String month() {		return monthFormat.format(new Date());	}	public static String month(Date date) {		return monthFormat.format(date);	}	public static String week() {		return week(new Date());	}	public static String week(Date date) {		return String.format("%s-W%s", yearFormat.format(date), weekFormat.format(date));	}	public static Date[] week(String week) {		String[] tokens = week.split("-W");		int year = Integer.valueOf(tokens[0]).intValue();		int weeks = Integer.valueOf(tokens[1]).intValue();		Calendar calendar = Calendar.getInstance();		calendar.set(Calendar.YEAR, year);		calendar.set(Calendar.WEEK_OF_YEAR, weeks + 1);		midnight(calendar);		Date begin = calendar.getTime();		calendar.add(Calendar.DATE, 7);		Date end = calendar.getTime();		return new Date[] { begin, end };	}	public static String local() {		return local(new Date());	}	public static String local(Date date) {		return String.format("%sT%s", dateFormat.format(date), timeFormat.format(date));	}	public static Date today() {		Calendar calendar = Calendar.getInstance();		calendar.setTime(new Date());		midnight(calendar);		return calendar.getTime();	}	public static Date tomorrow() {		Calendar calendar = Calendar.getInstance();		calendar.setTime(today());		calendar.add(Calendar.DATE, 1);		return calendar.getTime();	}	public static Date next(int days) {		return next(new Date(), days);	}	public static Date next(Date date, int days) {		Calendar calendar = Calendar.getInstance();		calendar.setTime(date);		calendar.add(Calendar.DATE, days);		midnight(calendar);		return calendar.getTime();	}	public static Date date(String string) {		String[] tokens = string.split("-");		Calendar calendar = Calendar.getInstance();		calendar.set(Calendar.YEAR, Integer.valueOf(tokens[0]).intValue());		calendar.set(Calendar.MONTH, Integer.valueOf(tokens[1]).intValue() - 1);		calendar.set(Calendar.DATE, Integer.valueOf(tokens[2]).intValue());		midnight(calendar);		return calendar.getTime();			}	public static Date year(int year) {		Calendar calendar = Calendar.getInstance();		calendar.add(Calendar.YEAR, year);		midnight(calendar);		return calendar.getTime();					}	public static int period() {		Calendar calendar = Calendar.getInstance();		int hours = calendar.get(Calendar.HOUR_OF_DAY);		if (hours < 12) {			return 1;		} else if (hours < 18) {			return 2;		} else {			return 3;		}	}	public static int age(Date birthday) {		Calendar person = Calendar.getInstance();		person.setTime(birthday);		Calendar today = Calendar.getInstance();		today.add(Calendar.YEAR, (-1) * person.get(Calendar.YEAR));		today.add(Calendar.MONTH, (-1) * person.get(Calendar.MONTH));		today.add(Calendar.DATE, (-1) * person.get(Calendar.DATE));		return today.get(Calendar.YEAR);	}	public static String taiwanDate() {		Calendar calendar = Calendar.getInstance();		int years = calendar.get(Calendar.YEAR) - 1970;		int months = calendar.get(Calendar.MONTH) + 1;		int days = calendar.get(Calendar.DATE);		return String.format("%d%02d%02d", years, months, days);	}}